def test_sdf_to_gjf_uses_bound_route_and_native_preflight(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """SDF 链路写入 GJF Artifact，并调用现有 Gaussian native 预检。"""

    monkeypatch.setenv("MINICHEM_MCP_WORKSPACE", str(tmp_path))
    sdf = tmp_path / "water.sdf"
    smiles_result = interchange.execute(
        "smiles2sdf", "format_conversion", {"inputs": {"smiles_list": ["O"]}}
    )
    generated = tmp_path / smiles_result["artifact_files"][0]["path"]
    sdf.write_bytes(generated.read_bytes())
    response = interchange.execute(
        "sdf_to_gjf",
        "format_conversion",
        {
            "inputs": {
                "sdf_path": "water.sdf",
                "route_parameters": {
                    "result": {"gaussian_code": "#p B3LYP/6-31G(d) SP"}
                },
            },
            "resource_limits": {"cpu_cores": 8, "memory_mb": 4096},
        },
    )
    assert response["status"] == "success"
    result = response["result"]
    assert result["route_section"] == "#p B3LYP/6-31G(d) SP"
    assert result["native_preflight_ready"] is True
    assert result["native_preflight"]["calculation_intent"] == "single_point"
    artifact = response["artifact_files"][0]
    assert artifact["semantic_type"] == "GaussianInputDeck"
    assert artifact["media_type"] == "chemical/x-gaussian-input"
    assert (tmp_path / artifact["path"]).read_text(encoding="utf-8").startswith("%nprocshared=")


