def test_sdf_to_gjf_rejects_multiple_valid_records_without_writing_a_deck(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """多记录 SDF 必须结构化失败，不能静默只转换第一条记录。"""

    monkeypatch.setenv("MINICHEM_MCP_WORKSPACE", str(tmp_path))
    smiles_result = interchange.execute(
        "smiles2sdf",
        "format_conversion",
        {"inputs": {"smiles_list": ["O", "C"]}},
    )
    source = tmp_path / smiles_result["artifact_files"][0]["path"]
    multiple_records = tmp_path / "multiple-records.sdf"
    multiple_records.write_bytes(source.read_bytes())

    response = interchange.execute(
        "sdf_to_gjf",
        "format_conversion",
        {
            "inputs": {
                "sdf_path": "multiple-records.sdf",
                "route_parameters": "#p PM6 SP",
            }
        },
    )

    assert response["status"] == "failed"
    assert response["error"]["code"] == "sdf_record_count_invalid"
    assert response["result"]["valid_record_count"] == 2
    assert response["artifact_files"] == []
    assert not list((tmp_path / "outputs").rglob("*.gjf"))


def test_sdf_to_gjf_rejects_invalid_leading_record_before_one_valid_record(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """首条记录损坏时，即使后续有一条有效记录也不得交给作者入口。"""

    monkeypatch.setenv("MINICHEM_MCP_WORKSPACE", str(tmp_path))
    smiles_result = interchange.execute(
        "smiles2sdf", "format_conversion", {"inputs": {"smiles_list": ["O"]}}
    )
    source = tmp_path / smiles_result["artifact_files"][0]["path"]
    malformed = tmp_path / "leading-invalid.sdf"
    malformed.write_bytes(
        b"bad\nbad\nbad\nnot counts\n$$$$\n" + source.read_bytes()
    )

    response = interchange.execute(
        "sdf_to_gjf",
        "format_conversion",
        {
            "inputs": {
                "sdf_path": "leading-invalid.sdf",
                "route_parameters": "#p PM6 SP",
            }
        },
    )

    assert response["status"] == "failed"
    assert response["error"]["code"] == "sdf_record_count_invalid"
    assert response["result"]["total_record_count"] == 2
    assert response["result"]["valid_record_count"] == 1
    assert response["artifact_files"] == []


def test_xyz_to_gjf_preserves_author_fields_and_rejects_route_injection(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """XYZ 链路保留入口字段，越界路径和多行 route 均被拒绝。"""

    monkeypatch.setenv("MINICHEM_MCP_WORKSPACE", str(tmp_path))
    (tmp_path / "water.xyz").write_text(_xyz(), encoding="utf-8")
    response = interchange.execute(
        "xyz_to_gjf",
        "format_conversion",
        {
            "inputs": {
                "input_xyz_path": "water.xyz",
                "route_section": "# M062X/6-31G(d) SP",
                "charge": -1,
                "multiplicity": 2,
                "title": "Bounded title",
            },
            "resource_limits": {"cpu_cores": 1, "memory_mb": 1024},
        },
    )
    assert response["status"] == "success"
    assert response["result"]["charge"] == -1
    assert response["result"]["multiplicity"] == 2
    assert response["result"]["atoms_written"] == 3

    with pytest.raises(ValueError, match="control|one bounded line"):
        interchange.execute(
            "xyz_to_gjf",
            "format_conversion",
            {
                "inputs": {
                    "input_xyz_path": "water.xyz",
                    "route_section": "#p B3LYP/6-31G(d) SP\n%Chk=outside.chk",
                }
            },
        )
    with pytest.raises(ValueError, match="escapes"):
        interchange.execute(
            "xyz_to_gjf",
            "format_conversion",
            {
                "inputs": {
                    "input_xyz_path": "../water.xyz",
                    "route_section": "#p B3LYP/6-31G(d) SP",
                }
            },
        )
    with pytest.raises(ValueError, match="filename, not a path"):
        interchange.execute(
            "xyz_to_gjf",
            "format_conversion",
            {
                "inputs": {
                    "input_xyz_path": "water.xyz",
                    "route_section": "#p PM6 SP",
                    "chk_file": "..",
                }
            },
        )


