def test_public_xyz_artifact_is_itself_native_valid_after_wrapper_normalization(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """公开 XYZ 交付的同一个 GJF 文件必须能直接交给 native 校验。"""

    monkeypatch.setenv("MINICHEM_MCP_WORKSPACE", str(tmp_path))
    monkeypatch.setenv("RESEARCHCHEMBENCH_AVAILABLE_CPU_CORES", "1")
    monkeypatch.setenv("RESEARCHCHEMBENCH_AVAILABLE_MEMORY_MB", "1024")
    monkeypatch.setenv("RESEARCHCHEMBENCH_AVAILABLE_GPU_COUNT", "0")
    (tmp_path / "water.xyz").write_text(_xyz(), encoding="utf-8")

    response = discovery_tools.execute_action(
        ProgressiveActionRequest(
            action_id="xyz_to_gjf",
            backend_id="format_conversion",
            inputs={
                "input_xyz_path": "water.xyz",
                "route_section": "#p PM6 SP",
            },
            resource_limits={"cpu_cores": 1, "memory_mb": 1024, "gpu_count": 0},
        )
    )

    assert response["status"] == "success"
    artifact = next(
        item
        for item in response["output_artifacts"]
        if item["semantic_type"] == "GaussianInputDeck"
    )
    generated = tmp_path / artifact["path"]
    assert generated.read_bytes().endswith(b"\n\n")
    assert not (generated.parent / "native_preflight.gjf").exists()
    assert response["provenance"]["wrapper_normalization"] == {
        "gaussian_coordinate_separator": "final_blank_line",
        "applied": True,
        "target": "same_output_artifact",
    }

    validation = validate_native_job(
        NativeJobRequest(
            software_id="gaussian",
            executable="g16",
            staged_inputs=[
                {"source_path": artifact["path"], "target_path": "inputs/generated.gjf"}
            ],
            stdin_target="inputs/generated.gjf",
            resource_limits={"cpu_cores": 1, "memory_mb": 1024, "gpu_count": 0},
            calculation_intent="other",
        )
    )
    # Gaussian 是否可用由 MiniChem 声明的 runtime 配置决定，不能用测试进程的 PATH 推断。
    if validation["status"] == "success":
        assert validation["valid"] is True
    else:
        assert validation["status"] == "unavailable"
        assert validation["error"]["code"] == "executable_missing"


