def test_public_smiles2sdf_members_handoff_to_sdf_to_gjf(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    """公开批量结果注入逐项 ArtifactRef，并可把单记录引用交给 SDF 转换。"""

    monkeypatch.setenv("MINICHEM_MCP_WORKSPACE", str(tmp_path))
    monkeypatch.setenv("RESEARCHCHEMBENCH_AVAILABLE_CPU_CORES", "1")
    monkeypatch.setenv("RESEARCHCHEMBENCH_AVAILABLE_MEMORY_MB", "1024")
    monkeypatch.setenv("RESEARCHCHEMBENCH_AVAILABLE_GPU_COUNT", "0")
    batch = discovery_tools.execute_action(
        ProgressiveActionRequest(
            action_id="smiles2sdf",
            backend_id="format_conversion",
            inputs={"smiles_list": ["O", "C"]},
            resource_limits={"cpu_cores": 1, "memory_mb": 1024, "gpu_count": 0},
        )
    )

    assert batch["status"] == "success"
    successful_records = batch["result"]["successful_records"]
    assert len(successful_records) == 2
    assert all(
        set(record["sdf_artifact"]) == {"artifact_id"}
        for record in successful_records
    )
    record_artifacts = [
        item
        for item in batch["output_artifacts"]
        if item["semantic_type"] == "SDFRecordFile"
    ]
    assert len(record_artifacts) == 2
    assert [record["sdf_artifact"] for record in successful_records] == [
        {"artifact_id": item["artifact_id"]} for item in record_artifacts
    ]
    assert all(_read_sdf_record_count(tmp_path / item["path"]) == 1 for item in record_artifacts)

    converted = discovery_tools.execute_action(
        ProgressiveActionRequest(
            action_id="sdf_to_gjf",
            backend_id="format_conversion",
            inputs={
                "sdf_path": successful_records[1]["sdf_artifact"],
                "route_parameters": "#p PM6 SP",
            },
            resource_limits={"cpu_cores": 1, "memory_mb": 1024, "gpu_count": 0},
        )
    )

    assert converted["status"] == "success"
    assert converted["result"]["native_preflight_ready"] is True
    assert converted["result"]["input_sdf_path"] == record_artifacts[1]["path"]
    gjf_artifact = converted["output_artifacts"][0]
    assert gjf_artifact["semantic_type"] == "GaussianInputDeck"
    assert gjf_artifact["parent_artifact_ids"] == [
        successful_records[1]["sdf_artifact"]["artifact_id"]
    ]


